/**
 * Refreshes VIP entitlement from backend server (e.g. on login or app foreground).
 * Authoritative metadata (isVip, productId, isLifetime, expiryTimeMillis) is saved.
 */
suspend fun refreshEntitlement(authRepo: AuthRepository): Boolean = withContext(Dispatchers.IO) {
    val session = authRepo.captureSession()
    val uid = session.uid ?: return@withContext false
    val backendUrl = getBackendUrl() ?: return@withContext false
    if (!authRepo.isCurrent(session)) return@withContext false

    val idToken = authRepo.getIdToken() ?: return@withContext false
    if (!authRepo.isCurrent(session)) return@withContext false

    try {
        val request = Request.Builder()
            .url("$backendUrl/v1/entitlements")
            .header("Authorization", "Bearer $idToken")
            .get()
            .build()

        httpClient.newCall(request).execute().use { response ->
            if (!authRepo.isCurrent(session)) {
                Log.w(TAG, "Ignoring stale refresh response because user session changed.")
                return@withContext false
            }

            if (response.isSuccessful) {
                val body = response.body?.string() ?: ""
                val json = JSONObject(body)
                val isVip = json.optBoolean("isVip", false)

                if (isVip) {
                    val productId = json.optString("productId", "vip_lifetime")
                    val isLifetime = json.optBoolean("isLifetime", productId == "vip_lifetime")
                    val expiry = if (json.has("expiryTimeMillis") && !json.isNull("expiryTimeMillis")) json.optLong("expiryTimeMillis") else null
                    val now = System.currentTimeMillis()

                    saveEntitlementMetadata(
                        uid = uid,
                        isVip = true,
                        productId = productId,
                        isLifetime = isLifetime,
                        expiryTimeMillis = expiry,
                        verifiedAt = now
                    )
                    val valid = isCachedVipValid(uid, now)
                    _isVipActive.value = valid
                    return@withContext valid
                } else {
                    revokeEntitlement(uid)
                    return@withContext false
                }
            } else if (response.code == 401 || response.code == 403) {
                revokeEntitlement(uid)
                return@withContext false
            }
        }
    } catch (e: Exception) {
        if (e is kotlinx.coroutines.CancellationException) throw e
        Log.w(TAG, "Transport failure during entitlement refresh: ${e.message}")
    }

    // Only fallback to cache if session is STILL current
    return@withContext if (authRepo.isCurrent(session)) {
        val valid = isCachedVipValid(uid)
        _isVipActive.value = valid
        valid
    } else {
        false
    }
}

